ruleToc.chapterList:
@js:
let href=baseUrl.match(/chapter\/(.*)\.html/)
let u=href[1]
//java.log(JSON.stringify(u))

let page=src.match(/value\="(.*?)"/g)
//java.log(JSON.stringify(page))

let nums=[];
page.forEach(function(number){
  let match=number.match(/\d+/);
  if(match){
    nums.push(parseInt(match[0],10));
  }
})

let max=nums.slice(-1)
//java.log(JSON.stringify(max))

let mc=baseUrl.match(/http[\S\s]*?com/)
java.log(JSON.stringify(mc))

//番茄小说
if(baseUrl.match(/www\.fanqxsw\.com/)){
let list=[];
for(let i=0;i<=max;i++){
  let url=`https://www.fanqxsw.com/index.php?action=loadChapterPage,{"body":"id=${u}&page=${i}","method":"POST"}`;
  list.push(url);
  //java.log(JSON.stringify(list))
}

let lt=java.ajaxAll(list).map(x=>x.body())
//java.log(JSON.stringify(lt))

lt.reduce((arr,item)=>{
 arr=arr.concat(JSON.parse(item).data);
	return arr
},[])
//可乐小说
} else if(baseUrl.match(/www\.kelexs\.com/)){

	let pg=src.match(/data-p\=\".*\"/g)
//java.log(JSON.stringify(pg))
let ns=[];
pg.forEach(function(Number){
  let matchs=Number.match(/\d+/);
  if(matchs){
    ns.push(parseInt(matchs[0],10));
  }
})

let maxs=ns.slice(-1)
//java.log(JSON.stringify(maxs))

	let list=[];
for(let i=0;i<=maxs;i++){
  let url=`https://www.kelexs.com/index.php?action=loadChapterPage,{"body":"id=${u}&page=${i}","method":"POST"}`;
  list.push(url);
  //java.log(JSON.stringify(list))
}

let lt=java.ajaxAll(list).map(x=>x.body())
//java.log(JSON.stringify(lt))

lt.reduce((arr,item)=>{
 arr=arr.concat(JSON.parse(item).data);
	return arr
},[])
//找书吧
} else if(baseUrl.match(/www\.zhaoshuba\.com/)){

	let pg=src.match(/data-p\=\".*\"/g)
//java.log(JSON.stringify(pg))
let ns=[];
pg.forEach(function(Number){
  let matchs=Number.match(/\d+/);
  if(matchs){
    ns.push(parseInt(matchs[0],10));
  }
})

let maxs=ns.slice(-1)
//java.log(JSON.stringify(maxs))

let list=[];
for(let i=0;i<=maxs;i++){
  let url=`https://www.zhaoshuba.com/index.php?action=loadChapterPage,{"body":"id=${u}&page=${i}","method":"POST"}`;
  list.push(url);
  //java.log(JSON.stringify(list))
}

let lt=java.ajaxAll(list).map(x=>x.body())
//java.log(JSON.stringify(lt))

lt.reduce((arr,item)=>{
 arr=arr.concat(JSON.parse(item).data);
	return arr
},[])
}

