@js:
    var sort = [];
    var push = (title, url, type) =>  
    sort.push({
      title: title,
      url: url,
      style: {
          layout_flexGrow: 1,
          layout_flexBasisPercent: type
       }
     });
     push("༺ˇ»`ʚ全部分类ɞ´«ˇ༻", "", "1")
    var url = source.getKey();
    var o = org.jsoup.Jsoup.parse(java.ajax(url));
    var s = o.select('nav.nav a');
    for(var i in s){
        if(i >= 3 && i <= 10){
        u = String(s[i].attr("href")).replace(/(.*)-(\d+)\//,"$1-{{page}}/");
        push(s[i].text(), u, "0.25")
        }
     };
     push("最近更新","/fenlei/{{page}}/","0.25");
     push("总榜","/rank/allvisit/","0.2");
     push("月榜","/rank/monthvisit/","0.2");
     push("周榜","/rank/weekvisit/","0.2");
     push("收藏","/rank/goodnum/","0.2");
    JSON.stringify(sort);

